//! Parse Rust source into a [`syn`] syntax tree, inspect it, and expand a
//! transformed version back into tokens.
//!
//! This crate is a thin proc-macro front end. The reusable parsing and
//! transformation logic lives in the [`passes`] module so it can be unit tested
//! without going through the compiler's macro expansion.

use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, File};

mod passes;

/// Parse the input as a Rust source file, run every transformation pass, and
/// expand to the rewritten items.
///
/// ```ignore
/// ast_transform::transform! {
///     fn greet() -> &'static str { "hello" }
/// }
/// ```
#[proc_macro]
pub fn transform(input: TokenStream) -> TokenStream {
    let file = parse_macro_input!(input as File);
    let file = passes::transform_file(file);
    quote!(#file).into()
}

//! Syntax-tree inspection and transformation passes.
//!
//! A pass is any type implementing [`syn::visit_mut::VisitMut`]. Add new passes
//! to [`transform_file`] and they will run in order over the whole tree.

use syn::{
    visit_mut::{self, VisitMut},
    File, Ident, ItemFn,
};

/// Run every transformation pass over `file` and return the rewritten tree.
pub fn transform_file(mut file: File) -> File {
    RenameFunctions.visit_file_mut(&mut file);
    file
}

/// Inspect the tree and append `_transformed` to every free function's name.
///
/// `visit_mut` recurses into nested modules, so functions in inline `mod`
/// blocks are rewritten too.
struct RenameFunctions;

impl VisitMut for RenameFunctions {
    fn visit_item_fn_mut(&mut self, node: &mut ItemFn) {
        let renamed = format!("{}_transformed", node.sig.ident);
        node.sig.ident = Ident::new(&renamed, node.sig.ident.span());
        visit_mut::visit_item_fn_mut(self, node);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use quote::ToTokens;

    fn parse(src: &str) -> File {
        syn::parse_str(src).expect("test input is valid Rust")
    }

    #[test]
    fn renames_free_functions() {
        let rendered = transform_file(parse("fn foo() {}")).into_token_stream().to_string();
        assert!(rendered.contains("fn foo_transformed"), "got: {rendered}");
    }

    #[test]
    fn leaves_other_items_untouched() {
        let rendered = transform_file(parse("struct Foo;")).into_token_stream().to_string();
        assert!(rendered.contains("struct Foo"), "got: {rendered}");
    }

    #[test]
    fn recurses_into_inline_modules() {
        let rendered = transform_file(parse("mod inner { fn bar() {} }"))
            .into_token_stream()
            .to_string();
        assert!(rendered.contains("fn bar_transformed"), "got: {rendered}");
    }
}

//! End-to-end test: invoke the proc macro and confirm the emitted items are
//! callable from the surrounding crate.

ast_transform::transform! {
    fn greet() -> &'static str {
        "hello"
    }
}

#[test]
fn macro_rewrites_function_names() {
    assert_eq!(greet_transformed(), "hello");
}

